#include <bits/stdc++.h>
#define maxn 1010
#define mo 1000000007
#define ll long long

using namespace std;

ll dp[maxn][maxn][2][2], n, k;
ll c[maxn][maxn], ans[maxn], fac[maxn];

int main() {
    scanf("%lld%lld", &n, &k);

    for (int i = 1; i <= n; ++i) {
        c[i][0] = c[i][i] = 1LL;
        for (int j = 1; j < i; ++j) {
            c[i][j] = (c[i - 1][j] + c[i - 1][j - 1]) % mo;
        }
    }

    fac[0] = 1LL;
    for (int i = 1; i <= n; ++i) {
        fac[i] = fac[i - 1] * i % mo;
    }

    dp[0][0][1][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            for (int now = 0; now < 2; ++now) {
                for (int ne = 0; ne < 2; ++ne) {
                    ll value = dp[i - 1][j][now][ne];

                    dp[i][j][ne][0] =
                        (dp[i][j][ne][0] + value) % mo;

                    if (!now) {
                        dp[i][j + 1][ne][0] =
                            (dp[i][j + 1][ne][0] + value) % mo;
                    }

                    if (i < n) {
                        dp[i][j + 1][ne][1] =
                            (dp[i][j + 1][ne][1] + value) % mo;
                    }
                }
            }
        }
    }

    for (int i = 0; i <= n; ++i) {
        for (int now = 0; now < 2; ++now) {
            for (int ne = 0; ne < 2; ++ne) {
                ans[i] = (ans[i] + dp[n][i][now][ne]) % mo;
            }
        }
        ans[i] = ans[i] * fac[n - i] % mo;
    }

    int flag = -1;
    for (int i = k + 1; i <= n; ++i) {
        ans[k] = (ans[k] + flag * c[i][k] % mo * ans[i] % mo + mo) % mo;
        flag *= -1;
    }

    printf("%lld\n", ans[k]);
    return 0;
}

